// Original workshops with short public-domain textual evidence. Source scenes are assigned reading.
const F=s=>`https://www.folger.edu/explore/shakespeares-works/macbeth/read/${s}/`;
const C='https://www.gutenberg.org/files/46/46-h/46-h.htm';
const make=d=>{
 const topic=d.topic||'macbeth',tid=topic==='carol'?'christmas-carol':topic==='skills'?'reading-writing':topic,id=`lit.${topic}.${d.key}`,ref=topic==='skills'?'3.3':topic==='carol'?'3.1.2':'3.1.1';
 const items=(stage,rows)=>rows.map(([prompt,correct,a,b,why,concept],i)=>{const answer=(i+d.key.length)%3,options=[a,b];options.splice(answer,0,correct);return{id:`${id}.${stage}.${i+1}`,prompt,options,answer,why,concept:`lit.${topic}.${d.key}.${concept}`};});
 return{id,topicId:`english-literature.${tid}`,title:d.title,scope:d.scope,minutes:d.minutes||30,refs:ref==='3.3'?['3.3']:[ref,'3.3'],author:d.author||(topic==='carol'?'Charles Dickens':'William Shakespeare'),rights:'public_domain',textType:topic==='carol'?'prose':'play',textTitle:d.textTitle||(topic==='carol'?'A Christmas Carol':'Macbeth'),readingURL:d.sources[0],sources:d.sources,checked:'29 October 2026',sourceNote:d.sourceNote||'Short public-domain textual evidence; original teaching analysis and workshop prompts. Read the full linked scene or stave. Interpretations and performance choices can differ; quotation punctuation is typographically normalised. Scene and line numbering may vary by edition.',contextReading:d.sources.map((url,i)=>({url,label:topic==='carol'?`A Christmas Carol · complete text${i?' (additional source)':''}`:`Assigned source ${i+1}`})),
 cards:d.cards,views:[{kind:'language',label:'Evidence decisions',title:d.scope,content:d.quote,words:d.details,readingRegion:d.quote.length>180},{kind:'people',label:'Compare perspectives',title:'Who can know or judge?',rows:d.people},{kind:'timeline',label:'Develop the argument',title:'Trace the reasoning',events:d.movement}],tasks:[[d.challenge[0],d.challenge.slice(1,4),0,d.challenge[4],d.challenge[5]]],practice:items('practice',d.practice),check:items('check',d.check),writing:d.writing,rubric:d.rubric,...(d.extra||{})};
};
export const batch10=[
make({topic:'skills',key:'lesson-06',title:'A sustained whole-text argument',scope:'Macbeth · recognition, insecurity and resistance',sources:[F('1/7'),F('3/1'),F('5/8')],quote:'To be thus is nothing,\nBut to be safely thus.',
 cards:[['Give the answer a direction','A whole-text argument is more than a journey through the plot. To discuss Macbeth’s pursuit of security, connect his recognition of obstacles, his insecurity after becoming king and his later resistance. Each stage should test a claim about what power provides or fails to provide. Read the linked scenes before planning.'],['Make development do analytical work','The distinction between being king and being safely king can qualify a claim that gaining the crown fulfils ambition. Relate the repeated word and the change introduced around it to later action. A paragraph advances the answer when its evidence changes or sharpens the thesis rather than simply proving that another event happened.'],['Include a limit that matters','Macbeth’s final resistance may complicate an account of complete passivity, even while it fails to undo his tyranny. Address counterevidence fairly. A qualified thesis can remain clear: the character’s choices pursue security but help destroy it. Select the parts of the play needed for that argument rather than force every scene into the response.']],details:[['thus','A deliberately indirect reference to the achieved position.'],['nothing','The achievement is dismissed without security.'],['safely','The qualification redirects desire towards a continuing need.']],people:[['Earlier Macbeth','Recognises reasons against killing.'],['Crowned Macbeth','Finds possession insufficient.'],['Reader','Tests a thesis against later resistance and its costs.']],movement:[['Thesis','Define the relation between power and security.'],['Development','Select a later change that tests it.'],['Counterevidence','Consider an action that complicates the claim.'],['Judgment','Refine the answer through the whole text.']],challenge:['Which plan develops a whole-text argument?','Linked moments show how the pursuit of security changes and undermines itself.','Every paragraph retells the next scene without testing a claim.','The conclusion ignores all evidence that complicates the opening.','Whole-text scope should develop reasoning rather than a plot list.','Ask what each later moment adds to or changes in the argument.'],practice:[['What should organise the response?','A question-led claim tested through selected developments.','The requirement to mention every scene equally.','A fixed device list unrelated to the question.','Selection should serve a developing interpretation.','argument'],['How can the qualification about safety be analysed?','It distinguishes possession of power from feeling secure in it.','It proves the crown ends every anxiety.','It makes every later decision irrelevant.','A small linguistic distinction can redirect a whole-text argument.','methods'],['What should counterevidence do?','Refine or qualify the thesis through a genuine complication.','Be concealed because it weakens a memorised answer.','Replace the need to reach any judgment.','A stronger argument accounts for evidence that resists it.','evaluation']],check:[['Which sequence is argumentative?','Recognised obstacles, unfulfilled security and a qualified final judgment.','A list of events with no relation to the question.','Only the first and last page numbers.','The relationship between moments gives the response direction.','structure'],['What makes a paragraph advance?','It adds a reason or qualification to the developing answer.','It repeats one point with another quotation.','It introduces an unrelated biography.','Progress is a change in reasoning, not only more text.','writing'],['Which claim needs correction?','The whole text must mean every scene receives equal space.','Later resistance can complicate a view of passivity.','Precise evidence can support a qualified thesis.','Whole-text understanding permits relevant selection.','scope'],['What should the conclusion do?','Judge the relation the selected evidence has developed.','Guarantee the response’s grade.','Add a new unsupported event.','Conclusions should follow the reasoning actually offered.','argument']],writing:'Develop a whole-play argument about how Macbeth’s pursuit of security affects his choices. Plan three connected claims, then write and revise a supported response.',rubric:['Sustain a question-led thesis rather than retell the plot.','Explain how selected moments develop or qualify that thesis.','Weigh counterevidence and reach a supported whole-text judgment.']}),
make({topic:'skills',key:'lesson-07',title:'A critical comparison',scope:'Macbeth / A Christmas Carol · isolation',author:'William Shakespeare / Charles Dickens',textTitle:'Macbeth and A Christmas Carol',sources:[F('3/2'),C],quote:'Macbeth: “O, full of scorpions is my mind, dear wife!”\n\nThe Carol narrator describes Scrooge as “secret, and self-contained, and solitary as an oyster.”',sourceNote:'Two short public-domain passages from Macbeth3.2 and A Christmas Carol Stave1. Labels are original attribution, not source wording. This is cross-text skills practice, not a claim that these texts are compared in an official exam question.',
 cards:[['Define the relation before the similarity','Macbeth’s image presents inward pressure during a conversation with his wife. Dickens’s narrator describes Scrooge’s social withdrawal from outside. Both offer ways to explore isolation, but one shared concern does not establish identical motives. First identify who presents each figure and how the reader gains access.'],['Compare the work of each image','The threatening creatures of Macbeth’s metaphor differ from the enclosing shell of the narrator’s simile. Explain what each comparison makes available to infer, then test it against the surrounding scene or stave. Do not make a universal code in which an animal always represents exactly one trait.'],['Judge what the difference contributes','A comparison can argue that the texts make isolation morally or emotionally complicated through different forms of access. Keep drama and narration distinct. Use linked evidence to explain the relation, rather than place two separate summaries side by side. This exercise develops comparison skills; it is not an official cross-text paper task.']],details:[['my mind','The character offers a self-description of inner pressure.'],['scorpions','An image of threat or pain needs its dramatic context.'],['self-contained','The narrator’s description emphasises separation and enclosure.']],people:[['Macbeth','Speaks about his mind within a relationship.'],['Carol narrator','Frames Scrooge’s habits for the reader.'],['Comparative writer','Distinguishes self-description from external presentation.']],movement:[['Locate','Identify voice and situation in each text.'],['Relate','Define a shared concern worth comparing.'],['Analyse','Explain different image functions.'],['Judge','Use the difference to refine the relation.']],challenge:['Which comparison preserves the evidence’s different positions?','Macbeth’s self-description and the narrator’s account offer different access to isolation.','Both lines are Scrooge confessing to his wife.','A shared animal image proves identical motives.','Voice and genre determine what kind of evidence each image supplies.','Ask who describes whom before making the situations equivalent.'],practice:[['What needs establishing first?','Each passage’s voice and situation.','That the two writers must share one intention.','Only the number of animal names.','Accurate attribution supports a meaningful relation.','voice'],['How should the images be compared?','Explain their different associations in context.','Treat every animal as a fixed symbol for evil.','Assume a simile and metaphor always have identical effects.','A term names a method; the local use needs analysis.','methods'],['What makes the comparison critical?','A supported judgment about the relation and a significant difference.','Only stating that both texts include isolation.','Replacing evidence with a universal moral claim.','Critical comparison evaluates a relationship through textual choices.','evaluation']],check:[['Which distinction is accurate?','A character’s spoken self-image differs from a narrator’s description.','Both passages are spoken by the same narrator.','A dramatic character always states the author’s final view.','Speaking position affects the kind of claim evidence can support.','voice'],['What should a comparative paragraph explain?','How linked details develop the shared focus differently.','Why every text must have one identical meaning.','Only the dates of publication.','A connection needs an explanation of relation and difference.','writing'],['Which claim overstates the evidence?','Both figures have the same reason for all their isolation.','Both passages permit discussion of enclosure or pressure.','Narrative access can affect the reader’s judgment.','A shared concern does not prove identical motives.','inference'],['How should this task be described?','An original exercise in cross-text critical comparison.','An official AQA Macbeth-versus-Carol question.','A complete assessment of the whole qualification.','Skill practice should not be misrepresented as exam format or attainment.','assessment']],writing:'Compare how the two passages present isolation. Analyse voice and imagery, then explain how the different forms of access affect your judgment of each figure.',rubric:['Establish a precise relation without assuming identical motives.','Analyse linked evidence with correct speaker or narrator attribution.','Explain a significant difference in the texts’ presentation.']}),
make({topic:'skills',key:'lesson-08',title:'Closed-book retrieval, timing and editing',scope:'Accurate reference and honest uncertainty',sources:[F('1/3'),F('1/7')],quote:'If chance will have me king, why, chance may crown me',
 cards:[['Retrieve what you can actually support','Before checking a text, write a short reference from memory and distinguish exact wording from a paraphrase. If uncertain, paraphrase honestly rather than supply invented words in quotation marks. Afterwards check speaker, scene and meaning. Confidence is useful information about a learner’s feeling, not proof of accuracy.'],['Allocate time to reasoning and checking','A short practice budget might allow five minutes to retrieve and plan, fifteen to write and five to check. This is advisory, not an enforced timer or official section rule. Leave time to correct references and sentence boundaries without expanding every sentence. Adjust the budget with a teacher where needed.'],['Keep retrieval and revision separate','The independent workspace records an unassisted memory-based response before criteria appear. After submission, verify it against the assigned text and save a revision. The task is retrieval practice, not the official Shakespeare extract format. Later recall through Review tests what returns after time has passed; immediate repetition alone does not establish lasting retention.']],details:[['If','The remembered qualification must not be silently removed.'],['chance','Agency and prediction are being considered, not finally resolved.'],['may','Modal uncertainty limits a claim of certainty.']],people:[['Retrieving writer','Distinguishes remembered wording from paraphrase.'],['Checking reader','Uses the assigned text to verify the first attempt.'],['Teacher','Calibrates timing and reviews actual writing.']],movement:[['Retrieve','Write without looking at the model.'],['Mark uncertainty','Label paraphrase where exact wording is unknown.'],['Verify','Check source, context and meaning.'],['Return later','Use due Review for delayed retrieval.']],challenge:['Which retrieval choice is most responsible?','Use an accurate paraphrase when exact wording is uncertain, then verify it after submission.','Invent a plausible quotation and treat confidence as proof.','Change a qualification to make the quotation easier to remember.','Evidence remains useful when its form and uncertainty are honestly recorded.','Do not use quotation marks to conceal uncertainty about the original words.'],practice:[['What should be labelled clearly?','Exact quotation versus paraphrase.','Only the longest remembered sentence.','A guessed grade as if it were official.','Clear distinctions prevent invented wording becoming evidence.','accuracy'],['What should an advisory budget preserve?','Time for planning, reasoning and checking, adjusted to need.','A compulsory automatic deadline for every learner.','A guarantee that speed proves quality.','Timing supports the work rather than measuring all ability.','planning'],['Why return to Review later?','To practise retrieval after a delay rather than only immediate repetition.','To claim that opening a page proves permanent memory.','To erase wrong first attempts.','Delayed practice is a different opportunity to test recall.','recall']],check:[['What is not proof of quotation accuracy?','The writer’s confidence alone.','A check against the assigned text.','Correct speaker and context.','Feeling certain and being accurate are different.','accuracy'],['When should checking and supported revision happen?','After preserving the first unassisted attempt.','By silently replacing the first response.','Before any attempt while claiming it was closed book.','Separate evidence of retrieval from later assistance.','independence'],['Which edit is necessary?','Correct a reference whose altered wording changes the meaning.','Add length without reconsidering support.','Replace evidence with a predicted grade.','Accuracy and reasoning matter more than cosmetic expansion.','editing'],['What limitation must the task retain?','It is memory practice, not the official Shakespeare extract task.','It guarantees a GCSE grade from recall alone.','Its suggested timing is an enforced examination rule.','Describe the practice and its evidence honestly.','assessment']],writing:'Practise a short memory-based argument in the independent workspace, then verify the references and save a separate revision.',rubric:['Use accurate references and distinguish paraphrase from exact wording.','Develop a coherent argument rather than a list of remembered fragments.','Verify and improve accuracy and expression after preserving the first attempt.'],extra:{independentWriting:true,independentTaskType:'retrieval',independentTaskLabel:'A closed-book retrieval practice response, not an official extract task.',independentIntro:'Work from memory first. If you cannot recall exact words, use a clearly labelled paraphrase. Suggested practice budget: 25 minutes; timing is not enforced.',independentPrompt:'From memory, give three brief references showing a change in Macbeth’s choices. Identify the context of each. Then develop one supported analytical paragraph. Label paraphrases honestly and do not invent quotations. Verify against the assigned text only after submitting this first response.',independentExtractLabel:'Memory-based practice · no supplied passage',independentExtract:''}}),
make({key:'workshop-01',title:'Act 1 close-reading and performance workshop',scope:'Act 1, scene 5 · disguise and direction',sources:[F('1/5'),F('1/7')],quote:'look like th’ innocent flower,\nBut be the serpent under ’t.',
 cards:[['Read the instruction as a dramatic action','Read the whole exchange before choosing a delivery. Lady Macbeth tells Macbeth how to appear while concealing another purpose. Identify the command, the comparison and the contrast between surface and hidden conduct. The language does something within a relationship, rather than merely illustrating a theme of deception.'],['Test two performance choices','Imagine the instruction delivered intimately as reassurance, then sharply as control. Compare how tone, distance and eye contact could affect an audience’s reading. These are production possibilities, not additional Shakespeare directions. Support a choice through the words and Macbeth’s responses rather than assuming one compulsory psychology.'],['Turn the staging into an argument','Choose the interpretation you can best support and explain what a contrasting choice reveals. A director may emphasise partnership or pressure without removing Macbeth’s responsibility. Write about the consequence for dramatic meaning; describing costumes alone is not an analysis of persuasion.']],details:[['look like','An imperative makes appearance a practical task.'],['innocent flower','A cultivated surface is offered for others to read.'],['serpent','Concealed threat contrasts with the visible image.']],people:[['Lady Macbeth','Directs an appearance and a plan.'],['Macbeth','Receives the instruction but remains an acting agent.'],['Director and audience','Encounter a particular performance of the relationship.']],movement:[['Script','Locate the instructions in the exchange.'],['Option A','Test intimacy and shared purpose.'],['Option B','Test urgency and pressure.'],['Judgment','Explain the choice through textual evidence.']],challenge:['Which performance argument is defensible?','Different delivery can emphasise partnership or pressure while the instruction remains deceptive.','The text demands one exact tone and distance in every production.','A costume choice removes Macbeth’s responsibility.','Performance interprets the script through choices it does not always prescribe.','Separate the words’ instruction from a director’s way of delivering it.'],practice:[['What is the speech doing?','Directing an appearance that conceals purpose.','Reporting a literal gardening lesson only.','Proving Macbeth cannot make any decision.','Interpret the instruction in its immediate dramatic relationship.','action'],['What should support a staging choice?','The words and the surrounding exchange.','Only a preferred costume colour.','A claim all audiences react identically.','Performance reasoning needs a connection to the script.','performance'],['What must an account of persuasion preserve?','Macbeth’s agency as well as Lady Macbeth’s pressure.','The claim he is a powerless object throughout.','A universal judgment about every woman.','One character’s tactic is not a universal law or a cancellation of choice.','agency']],check:[['What contrast organises the instruction?','Visible innocence and concealed threat.','Two identical literal flowers.','Public grief and a newspaper image.','The paired images give deception a visible form.','meaning'],['Which statement confuses script and production?','Shakespeare prescribes one compulsory whisper and exact eye contact here.','A production may choose an intimate delivery.','A sharper delivery can emphasise pressure.','A possible staging choice is not automatically an authorial direction.','performance'],['What makes the comment analytical?','It explains how delivery changes the relationship the audience perceives.','It lists costumes with no relation to meaning.','It only states that there is imagery.','Explain the consequence of a choice for dramatic meaning.','methods'],['What can an alternative performance do?','Test and qualify the initial interpretation.','Prove no textual evidence matters.','Guarantee the same response for every spectator.','Alternatives make interpretation reviewable when evidence is compared.','evaluation']],writing:'Propose and defend a performance of Lady Macbeth’s disguise instruction. Analyse the language, compare one alternative delivery and explain how the choice presents persuasion.',rubric:['Locate the instruction accurately within the relationship.','Connect concrete performance choices to wording and dramatic meaning.','Compare an alternative while preserving Macbeth’s agency.']}),
make({key:'workshop-02',title:'Act 2 sounds and staging workshop',scope:'Act 2, scene 2 · knocking and reported voices',sources:[F('2/2'),F('2/3')],quote:'Whence is that knocking?\nHow is ’t with me when every noise appalls me?',
 cards:[['Distinguish kinds of sound evidence','Read the stage knocking alongside Macbeth’s report of hearing a voice about sleep. A stage sound specified for the audience differs from a voice described by a character. A production may interpret the reported experience, but it should not be described as a compulsory independent ghost speaking aloud.'],['Compare practical and inward responses','Lady Macbeth tries to manage traces and movement while Macbeth finds noise alarming. Their responses can overlap with fear, guilt and the practical danger of discovery. Test a reading that attends to both. The knocking belongs to the external world but gains significance through the reactions it interrupts.'],['Design a justified pause','Choose where a pause or louder knock would sharpen pressure, then explain the script evidence supporting it. Timing is an interpretation, not a replacement for the words. An analysis should distinguish the sound itself, the character’s response and a possible audience inference.']],details:[['Whence','A question directs attention to an external intrusion.'],['every noise','The response expands beyond a single sound.'],['appalls','The word gives the disturbance emotional force.']],people:[['Macbeth','Reports experience and reacts with alarm.'],['Lady Macbeth','Attempts practical management of the aftermath.'],['Audience','Hears staged knocking but must interpret reported experience.']],movement:[['Classify','Separate staged sound from reported voice.'],['React','Compare the characters’ responses.'],['Stage','Choose a pause or sound emphasis.'],['Explain','Relate the choice to pressure and meaning.']],challenge:['Which distinction is accurate?','The script’s knocking differs from Macbeth’s report of a voice he heard.','Every reported voice must be an independently audible ghost.','No stage sound can affect dramatic meaning.','Sound evidence has different sources and degrees of certainty.','Ask whether the audience is directed to hear the sound or hears a character describe it.'],practice:[['Which is a specified external intrusion?','Knocking.','A verified ghost narrating every thought.','The audience’s own private memory.','Distinguish what is staged from what is reported.','sound'],['Why compare the two responses?','They reveal different ways of handling danger and distress.','They prove only one character can feel fear.','They erase the practical risk of discovery.','Practical action and emotional disturbance can coexist.','methods'],['What should justify a pause?','Its relation to wording, interruption and dramatic pressure.','Only the director’s preferred length in seconds.','A claim the pause is compulsory in every production.','Timing becomes analytical when its purpose is explained.','performance']],check:[['What makes the knocking significant?','Its interaction with the characters’ alarm and practical danger.','A rule that every knock means the same in every play.','Proof that Macbeth is already asleep.','Meaning comes from the sound’s position and response.','meaning'],['Which claim overstates the voice report?','It proves a literal ghost must speak independently in every production.','The report can represent Macbeth’s distress.','A director may interpret the experience differently.','Reported experience should not become compulsory external fact.','inference'],['Which comparison avoids a false opposition?','Lady Macbeth’s practical activity need not mean she feels no fear.','Action always proves complete emotional calm.','Only silence can express disturbance.','Conduct and feeling do not have a fixed one-to-one relation.','interpretation'],['What should a performance paragraph distinguish?','Script evidence, chosen timing and inferred response.','The actor’s costume and the poet’s birth date only.','Every spectator’s supposedly identical feelings.','A clear chain keeps observation and interpretation separate.','argument']],writing:'Analyse the knocking in Act 2, scene 2. Propose one timing choice and explain how it interacts with the characters’ different responses, distinguishing staged and reported sound.',rubric:['Distinguish audible stage evidence from a character’s report.','Explain sound and timing through the scene’s practical and emotional pressures.','Qualify performance choices and audience inferences using the actual stage evidence.']}),
make({key:'workshop-03',title:'Act 3 dialogue and public authority workshop',scope:'Act 3, scene 4 · the banquet',sources:[F('3/4')],quote:'You know your own degrees; sit down.',
 cards:[['Read social order as something performed','Macbeth begins the banquet by directing seating and recognising rank. Follow how that display of hospitality and authority is disrupted. A public scene allows the audience to compare an intended performance of order with actions that make it unstable. Read the whole banquet rather than isolate the opening instruction.'],['Track unequal access to the disturbance','Macbeth reacts to the ghost; the guests encounter his behaviour without necessarily sharing his sight. Lady Macbeth attempts explanations and control. A director’s decision about a visible ghost affects the theatre audience’s access, but it does not establish that every guest sees what Macbeth sees.'],['Compare public and private speech','Notice where speech addresses the gathering and where an intimate exchange tries to contain the crisis. Explain how changes in address, command and response affect the display of kingship. A useful paragraph follows the breakdown of a relationship or performance, not simply a sequence of supernatural appearances.']],details:[['degrees','The opening invokes a social hierarchy.'],['sit down','An instruction tries to organise the gathering.'],['your own','Recognition of rank makes public authority relational.']],people:[['Macbeth','Tries to host and govern a public encounter.'],['Guests','Interpret behaviour without full access to its cause.'],['Lady Macbeth','Attempts to manage the explanation and response.']],movement:[['Order','Establish seating and public welcome.'],['Disruption','Track the reaction that others cannot fully explain.'],['Containment','Compare private intervention and public speech.'],['Judgment','Assess the changed display of authority.']],challenge:['Which account preserves unequal knowledge?','The guests can witness Macbeth’s disturbance without necessarily seeing his ghost.','Every guest must see and identify the ghost.','Public authority is unaffected by how a gathering is managed.','A public scene can expose gaps between intention, sight and interpretation.','Track who sees, who reacts and who tries to explain.'],practice:[['What does the seating instruction establish?','An intended performance of hierarchy and order.','Proof every guest shares Macbeth’s thoughts.','A private diary with no audience.','The public situation matters to the command’s work.','authority'],['Why distinguish the guests’ access?','They can interpret behaviour without knowing its full cause.','They hear every private thought automatically.','They must see the same theatrical image as every spectator.','Dramatic knowledge is distributed unevenly.','methods'],['What can shifts in address reveal?','Attempts to manage public order through private intervention.','That every line addresses the same person in the same way.','That dialogue cannot shape authority.','Address is an action within a changing relationship.','dialogue']],check:[['What changes across the banquet?','A display of order becomes difficult to sustain.','All uncertainty is permanently resolved.','Macbeth has not yet received any crown.','The scene tests authority through a public encounter.','movement'],['Which staging claim needs qualification?','A visible ghost proves all guests share Macbeth’s sight.','The theatre audience’s access depends partly on staging.','A production can make reactions central.','The audience’s view and characters’ knowledge are distinct.','performance'],['What makes a dialogue analysis precise?','Identify who is addressed and how the relation changes.','Only count speaking turns.','Treat a private reply as a public proclamation without evidence.','Speech acts need their immediate audience and purpose.','methods'],['Which thesis can the scene support?','Public authority depends partly on a performance Macbeth cannot securely control.','Every guest learns all details of every murder.','A seating order guarantees moral legitimacy.','Interpret a developing pressure rather than invent universal knowledge.','argument']],writing:'How does the banquet test Macbeth’s public authority? Analyse commands and changes in address, and distinguish the guests’ knowledge from the theatre audience’s access.',rubric:['Follow the developing public encounter rather than retell ghost appearances.','Analyse precise dialogue and distribution of knowledge.','Qualify what a staging choice lets characters or spectators see.']}),
make({key:'workshop-04',title:'Act 4 warning and resistance workshop',scope:'Act 4, scenes 1–3 · confidence and grief',sources:[F('4/1'),F('4/2'),F('4/3')],quote:'But I must also feel it as a man.',
 cards:[['Separate assurance from interpretation','Macbeth hears warnings and apparently reassuring predictions, then draws conclusions about his safety. Read the actual wording alongside the inference he chooses. A statement can contain a qualification that a character discounts. Do not describe the consequences as proof that Macbeth never makes decisions.'],['Read resistance through human cost','The Macduff family scene and the later report put civilian loss beside political action. Macduff insists that feeling belongs to his response as a man. That can challenge a narrow equation of masculinity with immediate revenge, while not removing the later decision to act.'],['Build a contrast without simplifying it','Compare Macbeth’s narrowing confidence with a response that includes grief and action. Explain a specific word or turn in each scene. The comparison should not claim that one character has no feeling or the other no political aim; test the different relations between knowledge, emotion and choice.']],details:[['But','A corrective response complicates the preceding demand.'],['also','Feeling is added to action, not necessarily substituted for it.'],['as a man','The phrase contests what a gendered expectation can include.']],people:[['Macbeth','Selects interpretations that support confidence.'],['Macduff','Responds to personal loss within political resistance.'],['Malcolm','Urges action while hearing a different account of manhood.']],movement:[['Hear','Read the wording of warnings and assurances.'],['Infer','Distinguish Macbeth’s chosen conclusion.'],['Feel','Attend to the human cost of violence.'],['Act','Compare how feeling and political action relate.']],challenge:['Which reading respects the word also?','Macduff includes feeling within manhood without necessarily rejecting action.','He says feeling makes any action impossible forever.','He proves all male characters have identical values.','The reply expands the response rather than creating a simple either-or.','Read the corrective link between feeling and action.'],practice:[['What must be kept distinct?','A prediction’s wording and Macbeth’s inference of safety.','Every prediction and every later action as identical facts.','The poet and each character’s judgment.','Interpretation is part of the character’s conduct.','inference'],['What does also help establish?','Feeling and action can belong to the same response.','Grief must cancel every political intention.','Gender has one unchallenged meaning throughout the play.','The word qualifies the relation between two responses.','methods'],['Why include the family’s suffering?','It makes the human costs of political violence visible.','It proves civilian lives are irrelevant to kingship.','It supplies a complete psychological diagnosis.','A whole-play argument should attend to those harmed beyond the ruler.','cost']],check:[['What shapes Macbeth’s confidence?','His interpretation of the assurances he hears.','An absence of any warning.','A guaranteed exemption from all consequences.','The gap between wording and conclusion matters to agency.','meaning'],['Which statement avoids a false opposition?','Macduff can grieve while remaining committed to action.','A man must either feel nothing or never act.','Every character agrees on masculinity.','The reply complicates a restrictive expectation.','interpretation'],['What should a cross-scene argument analyse?','Different relations between knowledge, feeling and choice.','Only whether the scene numbers are consecutive.','A claim one character has no inner life.','Comparison requires a specific relationship and evidence.','argument'],['What should be avoided when discussing harm?','Treating civilian suffering only as a device for the ruler’s development.','Analysing how a report changes a political response.','Recognising loss beyond the central character.','Attend to represented victims as well as dramatic function.','perspective']],writing:'Compare how Act 4 presents confidence and resistance under pressure. Use the predictions and Macduff’s response to loss to analyse knowledge, feeling and choice.',rubric:['Separate wording from the inferences characters choose.','Analyse a precise turn in the relation between feeling and action.','Include the human costs of violence in the argument.']}),
make({key:'workshop-05',title:'Act 5 endings and theatrical choices workshop',scope:'Act 5, scene 8/5.9 · defeat and restoration',sources:[F('5/8'),F('5/5')],quote:'We shall not spend a large expense of time\nBefore we reckon with your several loves',
 cards:[['Distinguish defeat from the work of closure','Macbeth’s defeat and Malcolm’s final public address do different dramatic work. One ends a ruler’s resistance; the other attempts to organise a renewed political community. Folger combines material that some editions number as scenes 5.8 and 5.9. Read the full ending before deciding what restoration has achieved.'],['Choose what a final stage picture emphasises','A production might foreground the new king and gathering, or let the losses and damaged relationships remain visually present. Support a choice through the words and preceding action. A concluding ceremony can signal restoration without proving that every future problem has been solved.'],['Judge the costs of the resolution','Relate the ending to an earlier claim about order, safety or legitimacy. Explain what changes and what cannot simply be recovered. Do not replace a textual argument with a rule that all tragedies must end in complete despair or that a new monarch guarantees universal harmony.']],details:[['We','A public voice presents renewed collective authority.'],['time','The speech claims prompt attention to obligations.'],['reckon','An account of service and relationship contributes to restoration.']],people:[['Macbeth','Resists before defeat.'],['Malcolm','Makes a public claim to renewed order.'],['Audience','Interprets closure alongside remembered costs.']],movement:[['Defeat','Locate the end of resistance.'],['Address','Hear the new public voice.'],['Stage','Choose an emphasis for the final picture.'],['Evaluate','Weigh restoration against irrecoverable costs.']],challenge:['Which ending judgment is proportionate?','The address can stage restoration without proving that every future tension is resolved.','A new king guarantees permanent happiness for everyone.','Every tragedy must deny any possibility of renewed order.','Closure can perform a political change while leaving costs significant.','Test the final public claim against what the audience remembers.'],practice:[['What is distinct about Malcolm’s final speech?','It organises a public response after the defeat.','It is Macbeth’s private confession before Duncan’s murder.','It proves all previous deaths are reversed.','A final address does more than announce the outcome of combat.','closure'],['What should support a final stage picture?','Words, relationships and costs established by the play.','Only a preferred decorative backdrop.','An assumption every production must look identical.','Performance choices interpret textual pressures.','performance'],['Why note scene-number variation?','To locate the same ending accurately across editions.','To claim the plays have different central plots.','To require memorising one universal numbering system.','References should identify the moment without false certainty about edition labels.','references']],check:[['Which distinction helps analyse the ending?','Military defeat and political closure are related but different acts.','Every final speech belongs to Macbeth.','Restoration removes the need to consider victims.','Different dramatic actions contribute to resolution.','meaning'],['What is an unsupported guarantee?','The new order resolves all possible future conflict.','The speech presents a renewed public authority.','A production may emphasise remembered costs.','A performed intention is not proof of every future outcome.','inference'],['What should a whole-play conclusion connect?','The final change with an earlier question about authority or safety.','A new unsupported biography.','Only a list of deaths with no judgment.','Evaluation grows from the argument the play has developed.','argument'],['How can two productions differ defensibly?','They may give different weight to restoration and its costs using the same evidence.','One must ignore the script entirely.','Both must produce every spectator’s identical emotion.','Interpretations can differ while remaining textually accountable.','evaluation']],writing:'Defend a final stage picture for Macbeth. Explain how it weighs Malcolm’s attempted restoration against the costs of the play, and compare one alternative emphasis.',rubric:['Distinguish the outcome of combat from the final public address.','Support performance choices through wording and whole-play relationships.','Reach a qualified judgment about restoration and its costs.']}),
make({key:'workshop-06',title:'Ambition and self-deception evidence workshop',scope:'Acts 1 and 3 · recognising and repeating danger',sources:[F('1/7'),F('3/1')],quote:'I have no spur\nTo prick the sides of my intent, but only\nVaulting ambition',
 cards:[['Read recognition as evidence, not a cure','Macbeth identifies ambition as a motive after considering reasons against killing Duncan. Acknowledging the problem does not automatically stop him. Read the metaphor in the larger debate and ask what he understands, what he chooses and how those are different kinds of evidence.'],['Track what the achievement fails to settle','Later insecurity about possessing the crown can qualify the idea that ambition has a clear finishing point. Select a detail about safety and relate it to an earlier recognition. A developing argument can show a pattern of reasoning that justifies further harm, without claiming the character is incapable of self-awareness.'],['Test the self-deception claim','If arguing that Macbeth deceives himself, specify which conclusion he favours despite contrary evidence. Compare that claim with a reading of conscious risk-taking. Do not make self-deception a label that removes responsibility or explains every action without close analysis.']],details:[['no spur','The metaphor tests what can motivate the act.'],['but only','A restrictive turn isolates the named motive.'],['Vaulting','An image of excessive movement makes achievement unstable.']],people:[['Debating Macbeth','Recognises an inadequate or dangerous motive.'],['Crowned Macbeth','Seeks safety beyond possession.'],['Reader','Weighs self-deception beside conscious risk.']],movement:[['Recognise','Identify the motive explicitly named.'],['Choose','Distinguish awareness from conduct.'],['Repeat','Relate later insecurity to earlier reasoning.'],['Evaluate','Test self-deception against counterevidence.']],challenge:['Which claim separates awareness and choice?','Macbeth can recognise ambition’s danger and still choose action.','Naming a motive proves he cannot act on it.','Self-deception means he has no responsibility.','Knowledge of a reason is not a guarantee of corresponding conduct.','Compare what the speech recognises with the decision that follows.'],practice:[['What does the restrictive turn do?','It isolates ambition after other reasons are considered.','It proves ambition has vanished.','It makes context unnecessary.','The syntax is part of the speaker’s evaluation of motives.','methods'],['What can later insecurity qualify?','The idea that gaining the crown finishes the desire.','The fact Macbeth became king.','The existence of the earlier debate.','Later evidence can change a thesis about what ambition seeks.','development'],['What must a self-deception argument specify?','The favoured conclusion and the evidence that resists it.','Only that the character is bad.','A universal diagnosis with no scene reference.','A psychological label needs a precise textual argument.','evaluation']],check:[['What does recognition not guarantee?','That Macbeth will reject the contemplated act.','That the motive can be analysed.','That the speech contains a debate.','Awareness and moral conduct remain distinct.','agency'],['Which reading deserves consideration as an alternative?','Conscious risk-taking despite known objections.','That the entire speech occurs after the final battle.','That ambition is never named.','Alternatives should arise from the actual evidence.','interpretation'],['How should the metaphor be used?','Explain how excessive movement bears on unstable ambition.','Apply one fixed meaning to every horse image.','Only identify a noun without reasoning.','The image needs its work within this debate explained.','methods'],['What makes a cross-act claim stronger?','It tests a pattern while recognising changes in position.','It treats every speech as identical.','It ignores evidence against the preferred label.','Development is more precise than a fixed-trait summary.','argument']],writing:'Evaluate whether Macbeth’s pursuit of power involves self-deception or conscious risk. Analyse an early recognition and a later insecurity, weighing evidence for both readings.',rubric:['Define the interpretive claim precisely rather than use a fixed label.','Analyse linked evidence showing recognition, choice and later development.','Weigh a supported alternative while preserving responsibility.']}),
make({key:'workshop-07',title:'Gender and persuasion argument workshop',scope:'Act 1, scene 7 / Act 4, scene 3',sources:[F('1/7'),F('4/3')],quote:'When you durst do it, then you were a man.',
 cards:[['Identify the tactic before generalising','Lady Macbeth links a proposed action to a judgment about manhood. Locate the challenge within an attempt to change Macbeth’s decision. A character’s persuasive claim is not automatically Shakespeare’s moral rule or a reliable description of every man or woman.'],['Compare the term in another exchange','Macduff’s later insistence on feeling as a man supplies a different use of the gendered expectation. Explain how a word can be contested across the play. The comparison should not turn either character into a spokesperson for every historical audience or remove the pressure of each immediate situation.'],['Develop an argument about agency','Assess how the tactic works with Macbeth’s own ambitions and decisions. Pressure matters, but influence is not the same as total control. A strong paragraph can acknowledge the force of the challenge while explaining why responsibility remains shared or differently located.']],details:[['When','A condition makes recognition dependent on conduct.'],['durst','Daring is used as a measure in the challenge.'],['a man','A gendered judgment becomes a persuasive lever.']],people:[['Lady Macbeth','Uses a conditional judgment to apply pressure.'],['Macbeth','Responds within an existing ambition and decision.'],['Macduff','Later contests a narrow account of manhood.']],movement:[['Locate','Identify the decision being challenged.'],['Analyse','Explain the condition and value judgment.'],['Compare','Read a later competing use.'],['Judge','Separate influence from total control.']],challenge:['Which argument handles the tactic responsibly?','A character uses manhood as pressure, while a later exchange contests its meaning.','The line states Shakespeare’s universal definition of every man.','Persuasion proves Macbeth has no agency.','A dramatic claim has a speaker, purpose and competing contexts.','Ask who benefits from this definition at this moment.'],practice:[['What is the immediate purpose of the challenge?','To pressure Macbeth towards the proposed action.','To provide a neutral dictionary definition.','To report the final battle.','Read the speech as an action within a relationship.','persuasion'],['Why compare Macduff’s use?','It shows the term can carry a contested expectation.','It proves all characters mean exactly the same thing.','It cancels the need for textual evidence.','A recurring concept can change through different speakers.','methods'],['Which distinction matters to responsibility?','Influence differs from total control.','Every pressured person is automatically without agency.','Ambition becomes irrelevant once someone speaks.','Explain interaction without erasing a character’s decisions.','agency']],check:[['What does the condition imply?','Recognition of manhood is made dependent on daring the act.','The act has already occurred before the debate.','No value judgment is being made.','Syntax can make identity into leverage.','meaning'],['Which generalisation should be avoided?','A character’s tactic proves what every woman or man believes.','A later speech can challenge the expectation.','The context shapes the word’s function.','Keep a particular speech distinct from a universal claim.','interpretation'],['What makes the cross-scene comparison analytical?','Explain how different purposes shape the repeated concept.','Only count occurrences of the word man.','Ignore the different situations.','The relation needs function and context.','comparison'],['Which judgment is qualified?','The tactic exerts pressure while Macbeth remains responsible for choices.','The line makes Macbeth an entirely passive object.','Only one character has any motive.','Responsibility needs an account of both influence and action.','argument']],writing:'How does Shakespeare make gendered expectations a means of persuasion and debate? Compare Lady Macbeth’s challenge with Macduff’s response to grief, preserving context and agency.',rubric:['Analyse a persuasive tactic in its specific dramatic situation.','Compare a contested concept through precise language in both exchanges.','Avoid stereotypes and distinguish influence from total control.']}),
make({key:'workshop-08',title:'Friendship and betrayed trust workshop',scope:'Act 3, scene 1 · suspicion and hospitality',sources:[F('3/1'),F('3/3')],quote:'Thou hast it now—king, Cawdor, Glamis, all\nAs the Weïrd Women promised, and I fear\nThou played’st most foully for ’t.',
cards:[['Distinguish suspicion from complete knowledge','Banquo connects Macbeth’s new titles with the predictions and suspects wrongdoing. The phrase I fear marks a judgment, not an eyewitness account of Duncan’s murder. His following thoughts about his own descendants complicate any description of him as entirely untouched by the predictions.'],['Read hospitality beside surveillance','Macbeth calls Banquo a chief guest while asking about his travel and Fleance. A public invitation can appear friendly while information serves a hidden plan. Explain the gap between the two characters’ knowledge; do not assume Banquo hears Macbeth’s subsequent private reasoning or instructions to the murderers.'],['Argue about trust through the dramatic sequence','Move from Banquo’s private suspicion to the public invitation and then Macbeth’s private planning. That sequence lets an audience reassess courteous language. It supports an argument about betrayed trust without proving that Banquo has planned a rebellion or knows every detail of the threat.']],details:[['I fear','A suspicion is voiced without claiming direct observation.'],['foully','An evaluative word challenges the legitimacy of success.'],['all','The accumulated titles invite a reckoning with their acquisition.']],people:[['Banquo','Suspects wrongdoing and considers his own promised descendants.'],['Macbeth','Presents hospitality while gathering useful information.'],['Audience','Can connect the invitation with later private planning.']],movement:[['Suspect','Hear Banquo’s private inference.'],['Welcome','Read the public invitation.'],['Question','Consider how travel information is used.'],['Reassess','Return to courteous language after the murder plan.']],challenge:['What does Banquo’s speech establish?','He suspects wrongdoing, but the speech does not prove a planned rebellion.','He witnessed every action in Duncan’s chamber.','He hears all Macbeth’s private instructions.','An inference can be strong while knowledge remains incomplete.','Separate what Banquo suspects from what the audience subsequently hears.'],practice:[['Why does I fear matter?','It marks Banquo’s concern as an inference.','It proves he committed Duncan’s murder.','It makes the predictions irrelevant to him.','The qualification locates a speaker’s knowledge.','knowledge'],['How can the invitation acquire irony?','Later private planning changes an audience’s understanding of hospitality.','All courteous language always means murder.','Banquo narrates the murderers’ instructions.','Sequence gives the public exchange a second significance.','sequence'],['Which claim is least justified?','Banquo’s suspicion proves he has organised a rebellion.','Macbeth asks about Banquo’s movements.','Banquo thinks about the promised descendants.','Suspicion alone does not establish a further political action.','limits']],check:[['Which distinction is central to the opening speech?','Suspicion differs from eyewitness knowledge.','Banquo knows everything the audience will hear.','Every prediction has already been fulfilled.','Track the boundary of a character’s information.','meaning'],['What can the travel questions reveal in context?','Apparently friendly interest can serve a concealed plan.','They demonstrate that Macbeth has no interest in Fleance.','They are an official confession spoken to Banquo.','Read their function alongside the subsequent planning.','methods'],['Why consider Banquo’s thoughts about descendants?','They complicate an entirely disinterested portrait of him.','They prove he murders Duncan himself.','They establish that he hears all private speeches.','A qualified reading includes evidence that complicates admiration.','interpretation'],['What would strengthen a paragraph on betrayed trust?','Link the public welcome to the later private murder plan.','Retell only the battle in Act 1.','Invent a speech in which Banquo declares rebellion.','Use a precise dramatic relation rather than an invented event.','argument']],writing:'How does the sequence of private suspicion, public hospitality and private planning expose betrayed trust? Analyse two moments and distinguish Banquo’s knowledge from the audience’s.',rubric:['Keep suspicion, direct knowledge and audience information distinct.','Explain how the sequence changes the function of courteous language.','Qualify a claim about friendship using Banquo’s own hopes and Macbeth’s decisions.']}),
make({key:'workshop-09',title:'Violence and civilian suffering workshop',scope:'Act 4, scenes 2–3 · the family beyond the ruler',sources:[F('4/2'),F('4/3')],quote:'Whither should I fly?\nI have done no harm.',
cards:[['Let the victim’s question shape the reading','Lady Macduff asks where she can flee and asserts that she has done no harm. Innocence offers no practical protection in the situation. Read her following reflection on a world in which doing harm can be praised: the short quotation begins a political judgment rather than a simple reassurance of safety.'],['Separate action, report and production choice','The son’s stabbing is staged; Lady Macduff flees followed by the murderers. The later report establishes the family’s deaths. A production can choose how much violence to show, but a particular camera shot, scream or lighting effect is not automatically prescribed by the text. Compare what is witnessed with what is reported.'],['Keep civilian lives in the argument','The domestic conversation gives the family voices before the attack. The scene is more than a device to motivate Macduff’s revenge: it allows audiences to consider the costs of arbitrary power beyond the central ruler. Discuss a staging choice without treating suffering as merely spectacle or claiming every audience responds identically.']],details:[['Whither','The question searches for a possible route to safety.'],['no harm','Moral innocence is asserted without securing protection.'],['I','The threatened person speaks, rather than remaining an abstract casualty.']],people:[['Lady Macduff','Questions her danger and the world’s moral order.'],['Her son','Speaks and resists before suffering violence.'],['Macduff','Later receives a report of losses he did not witness.']],movement:[['Converse','Attend to the family’s domestic voices.'],['Warn','Hear the messenger’s urgent advice.'],['Threaten','Distinguish staged action from what follows offstage.'],['Report','Read the later account and its human consequence.']],challenge:['Which production note is most textually responsible?','Show the staged threat and explain any additional violence as a directorial choice.','Claim the play prescribes a modern close-up of every death.','Erase the family’s speech because only revenge matters.','Performance analysis distinguishes script evidence from an imagined production.','Ask what is actually staged, reported or chosen by a director.'],practice:[['Why read beyond I have done no harm?','The following lines question a world where innocence is unsafe.','They confirm a guaranteed escape.','They reveal that Lady Macduff planned Duncan’s murder.','A short quotation needs its surrounding argument.','context'],['What is the difference between the two scenes?','One presents the family’s danger; the other includes a report of their deaths.','Macduff witnesses every moment of the attack.','Both contain the same eyewitness narrator.','Location and access to events shape responses.','structure'],['Why attend to the family’s dialogue?','It gives the victims particular voices and relationships.','It proves all suffering is merely comic relief.','It makes political power irrelevant.','The human cost becomes specific through dramatic attention.','voices']],check:[['What does the question Whither should I fly suggest?','A threatened person searches for a possible refuge.','She announces a certain and safe escape.','She orders the attack on her household.','Read uncertainty within the immediate danger.','meaning'],['Which detail is a production choice rather than a necessary textual fact?','A camera lingering on a particular object during the attack.','The son speaks before the attack.','The family’s deaths are later reported.','Do not convert an imagined staging into evidence from the script.','performance'],['Which argument attends to civilian suffering?','The scene makes arbitrary power’s cost visible through a family’s voices.','The family matters only as an object for revenge.','Only royal characters experience harm.','An argument can recognise a plot function without reducing lives to it.','interpretation'],['How should an audience effect be expressed?','The sequence may unsettle viewers by exposing innocence without protection.','Every audience must enjoy the violence in exactly the same way.','No audience could respond to the family’s speech.','Effects require evidence and appropriate qualification.','argument']],writing:'How does Shakespeare make the suffering of people outside the royal household significant? Use Lady Macduff’s question, a structural detail and one clearly labelled production possibility.',rubric:['Explain a victim’s speech within the surrounding scene.','Distinguish staged action, later report and a possible production choice.','Connect civilian suffering to power without reducing the family to a plot device.']}),
make({key:'workshop-10',title:'Kingship context and audience interpretations',scope:'Act 4, scene 3 · virtue, testing and legitimacy',sources:[F('4/3'),F('1/4')],quote:'the king-becoming graces',
cards:[['Read the list within a test','Malcolm names qualities fitting a king while pretending to lack them. He is testing Macduff’s commitment to Scotland. The list is evidence of an articulated political ideal, but the speaker’s performance means it cannot simply be treated as an unqualified autobiographical confession. Read the exchange and its eventual clarification.'],['Connect a contextual idea to a textual choice','Questions of legitimate succession and a ruler’s duties help frame the play’s conflict. Explain how the vocabulary of fitting virtues makes conduct relevant to kingship alongside inherited position. A contextual sentence should illuminate this exchange; an unrelated list of historical dates does not analyse the language.'],['Allow differences within an audience','A viewer might welcome the ideal of responsible rule while questioning how political trust is tested through deception. These readings can coexist if supported. Avoid claiming that every early audience held a single opinion or that the list guarantees every future act of Malcolm’s government. Context informs interpretation rather than mechanically deciding it.']],details:[['king','The qualities are linked to the responsibilities of rule.'],['becoming','The word describes what is fitting, not only what is inherited.'],['graces','A favourable moral vocabulary frames the ideal being discussed.']],people:[['Malcolm','Performs a test before clarifying his claims.'],['Macduff','Has to judge conduct and allegiance under uncertainty.'],['Audience','Can consider the ideal and the troubling means of testing trust.']],movement:[['Frame','Locate a conversation about political trust.'],['Perform','Recognise Malcolm’s pretended failings.'],['Test','Read Macduff’s response to the claims.'],['Qualify','Connect the ideal with the method used to establish trust.']],challenge:['Which contextual argument stays connected to the passage?','The language of fitting virtues makes a ruler’s conduct part of political legitimacy.','A historical date alone proves the meaning of every word.','All early audiences necessarily agreed on every ruler.','Context earns its place by explaining a specific textual choice.','Link the political idea to becoming and graces.'],practice:[['Why does the test matter?','Malcolm’s claims cannot be read as a straightforward confession.','It proves every claim in the play is false.','It removes Macduff from the conversation.','Speech has a tactical situation and an eventual clarification.','speaker'],['What does becoming suggest here?','Qualities fitting the role of a king.','Only the physical act of growing older.','A guarantee that inherited power is always good.','Meaning follows the phrase’s political and moral context.','methods'],['Which audience claim is defensible?','Viewers may value responsible rule while questioning deceptive testing.','Every viewer must have an identical political opinion.','No viewer can consider more than one aspect.','A qualified effect can acknowledge tensions in the exchange.','audience']],check:[['What is essential context within the scene?','Malcolm is testing Macduff through pretended failings.','Malcolm has just privately confessed the murder of Duncan.','Macduff has no opportunity to respond.','Read the words through the dramatic situation.','meaning'],['How can context support analysis?','Explain how the virtues connect conduct with legitimate rule.','Replace textual discussion with unrelated background facts.','Assume a date dictates a single interpretation.','Connect background ideas to a method in the passage.','context'],['Which conclusion exceeds the evidence?','The list guarantees every future action of Malcolm’s rule.','The phrase presents fitting qualities for kingship.','The conversation tests political trust.','An ideal articulated now is not a record of all future conduct.','limits'],['What makes an alternative reading useful?','It explains how trust is pursued through a troubling performance.','It ignores the exchange in order to sound unusual.','It depends only on an invented audience survey.','An alternative must be grounded in dramatic evidence.','interpretation']],writing:'How does the conversation about king-becoming graces connect good rule with the problem of trust? Analyse the phrase, Malcolm’s test and a qualified audience interpretation.',rubric:['Locate the moral vocabulary within Malcolm’s deliberate test.','Use political context to explain a specific textual choice.','Offer a qualified interpretation without inventing a unanimous audience or a guaranteed future.']}),
make({key:'workshop-11',title:'Critical interpretations debate and evidence challenge',scope:'Acts 1 and 3 · fate, agency and counter-evidence',sources:[F('1/3'),F('1/7'),F('3/1')],quote:'If chance will have me king, why, chance may crown me\nWithout my stir.',
cards:[['Turn a reading into a testable claim','The possibility of being crowned without action can support a reading of Macbeth as tempted to wait upon fate. The conditional If and modal may keep the thought hypothetical. Do not convert a possibility entertained at one moment into proof that the character never makes decisions elsewhere.'],['Give a rival reading its best evidence','An agency argument can use the later debate about murder and the deliberate planning against Banquo. A fate argument can point to the predictions’ power over expectations. Test each against inconvenient evidence rather than creating a weak rival merely to dismiss it. An interpretation needs a precise account of both pressure and conduct.'],['Reach a qualified judgment','A useful judgment may argue that prophecy changes the possibilities Macbeth imagines while his choices help turn expectation into violence. That relation explains more than either a wholly controlled puppet or a person untouched by prediction. It remains an interpretation to defend, not the only wording a student is permitted to use.']],details:[['If','The thought begins with a condition rather than a certainty.'],['may','The imagined outcome remains a possibility.'],['Without my stir','Inaction is entertained here; later action tests its reach.']],people:[['Fate advocate','Uses the influence of predictions on expectations.'],['Agency advocate','Uses deliberation and deliberate planning.'],['Critical reader','Tests both against contrary evidence and qualifies the judgment.']],movement:[['Propose','State a claim that could be tested.'],['Support','Choose the strongest relevant evidence.'],['Challenge','Find a moment the claim struggles to explain.'],['Refine','Revise the claim to account for the tension.']],challenge:['Which judgment best handles both sets of evidence?','Prophecy shapes expectation while Macbeth’s choices help produce violence.','One hypothetical line proves Macbeth never acts.','Planning a murder proves he never hears predictions.','A qualified relation accounts for pressure and conduct together.','Check whether the judgment explains evidence that challenges it.'],practice:[['What does may establish?','A possibility rather than a guaranteed rule for all later events.','An unconditional command to murder Duncan.','A report of Banquo’s death.','Modal wording limits the strength of an inference.','modal'],['Which counter-evidence tests a pure puppet reading?','Macbeth deliberates and later plans violence.','The play has a title.','The first line appears early in the play.','Use an event relevant to decisions rather than an unrelated fact.','counter'],['What is a fair critical debate?','Test each reading against its strongest and most awkward evidence.','Give a rival an obviously false quotation.','Accept any claim because it is different.','Alternatives require evidence, accuracy and a reasoned judgment.','debate']],check:[['What kind of thought is the displayed passage?','A conditional possibility of kingship without action.','A direct instruction to kill Banquo immediately.','A final statement that all action is impossible.','Its grammar limits what it establishes.','meaning'],['What should happen when a claim cannot explain later planning?','Qualify or revise its account of agency.','Remove the later scenes from consideration.','Invent a new line that makes the claim true.','Whole-play reasoning responds to contrary evidence.','argument'],['Which rival reading deserves serious consideration?','One supported by relevant predictions and their effect on expectation.','One supported only by the number of pages.','One that deliberately misattributes every speech.','A strong rival helps make the final judgment more precise.','interpretation'],['What is the role of the final judgment?','Explain the relation between pressures and choices using evidence.','Declare that disagreement makes evidence unnecessary.','Repeat a label without explaining its scope.','A judgment should show what the tested evidence warrants.','evaluation']],writing:'Debate the claim that Macbeth is controlled by fate. Present the strongest evidence for it, test it against a deliberate decision and reach a qualified judgment.',rubric:['Use conditional wording accurately rather than converting possibility into certainty.','Represent a competing reading fairly and test it with relevant counter-evidence.','Reach a qualified whole-play judgment about the relation between pressure and choice.']}),
make({key:'workshop-12',title:'Accurate quotation and reference retrieval',scope:'Act 1, scene 4 · wording, speaker and dramatic position',sources:[F('1/4'),F('1/7')],quote:'Stars, hide your fires;\nLet not light see my black and deep desires.',
cards:[['Retrieve before checking the source','Close the text briefly and recall the speaker, moment and a short phrase. Then reopen the full scene and compare your attempt with the displayed wording. Accuracy is a result of checking, not a feeling of confidence. The title award to Malcolm matters to the aside’s immediate position.'],['Keep quotation and paraphrase honest','If unsure of exact wording, write an accurate reference in your own words without quotation marks. Do not repair a half-remembered quotation by inventing Shakespearean language. A short accurate phrase with analysis is more useful than a long inaccurate string. Editions can vary in spelling or punctuation; meaning and attribution still need care.'],['Make the retrieved reference do analytical work','The commands to stars and light make concealment part of the expression of desire. Locate the aside after Malcolm is named successor and contrast it with Macbeth’s public loyalty. The reference now supports an argument about a public-private divide rather than serving as an isolated memory trophy.']],details:[['hide','An imperative imagines concealment as something to command.'],['light see','Personification makes exposure feel like observation.'],['deep desires','The language places the wish beneath public presentation.']],people:[['Macbeth','Speaks an aside after a public exchange.'],['Duncan','Has publicly named Malcolm as successor.'],['Audience','Hears desire that is not presented as a public announcement.']],movement:[['Recall','Try wording and attribution without the source.'],['Verify','Check the linked scene and correct inaccuracies.'],['Locate','Restore the immediate dramatic situation.'],['Apply','Use a short accurate reference in an argument.']],challenge:['What should you do if the exact wording is uncertain?','Use an accurate paraphrase without quotation marks, then check the source.','Invent a plausible phrase and put it in quotation marks.','Attribute it to whichever character fits the essay.','Honest reference keeps memory uncertainty from becoming false evidence.','Separate exact words from your own account of their meaning.'],practice:[['Who speaks the displayed words?','Macbeth in an aside.','Banquo giving a public coronation speech.','Lady Macduff warning her son.','Attribution determines whose desires are being expressed.','speaker'],['What gives the aside immediate significance?','Malcolm has been named successor in the preceding exchange.','Banquo has already been murdered onstage.','Macbeth is speaking at the final restoration.','A reference is stronger when its position is accurate.','location'],['How does hide contribute to the argument?','The command makes concealment part of the expression of desire.','It proves the stars literally obey the speaker.','It establishes that no desire exists.','Analyse figurative action without treating it as literal astronomy.','methods']],check:[['Which is an honest paraphrase?','Macbeth wishes his desires to remain concealed.','“Macbeth wants the cosmos to make him invisible forever.”','“Banquo commands the moon to murder Duncan.”','A paraphrase uses your own wording without invented quotation marks.','accuracy'],['Which speech context is correct?','An aside following the naming of Malcolm as successor.','A public confession to Duncan after the murder.','A report from the murderers after Banquo’s death.','Speaker and placement are part of accurate reference.','meaning'],['What does the personification of light help explore?','The fear or wish surrounding exposure of private desire.','A scientific claim about how stars think.','Proof that Duncan hears every private thought.','Method analysis connects imagined observation with concealment.','methods'],['What is the best use of a retrieved phrase?','Embed it accurately and explain its role in a relevant claim.','Display it without a speaker or any explanation.','Add invented words to make it sound longer.','Retrieval serves reasoning rather than replacing it.','argument']],writing:'From memory, write a short reference to Macbeth’s concealment of desire. Check it against the source, correct any errors, and develop a paragraph connecting the aside to his public loyalty.',rubric:['Keep exact quotation, accurate paraphrase and uncertain memory clearly distinct.','Identify the correct speaker and dramatic moment before applying evidence.','Explain how a precise word supports a claim about public and private presentation.']}),
make({key:'workshop-13',title:'Comparative analytical paragraphs across the play',scope:'Act 2, scene 2 and Act 5, scene 1 · washing and control',sources:[F('2/2'),F('5/1')],quote:'Act 2 · Lady Macbeth: A little water clears us of this deed.\nAct 5 · Lady Macbeth: Out, damned spot, out, I say!',sourceNote:'Two separately attributed short public-domain quotations. The Act labels are teaching labels, not part of the speeches. Original analysis compares the scenes; read both complete scenes. No clinical diagnosis or fixed production is inferred from the text.',
cards:[['Give each moment its own situation','After Duncan’s murder, Lady Macbeth claims that water will clear them of the deed. In the later sleepwalking scene she repeatedly commands a spot to leave while others observe her hand-rubbing. The first is a confident claim, the second a troubled performance; do not treat them as the same kind of utterance.'],['Make the comparison through a precise method','Little reduces the apparent scale of the remedy; repeated commands in the later scene struggle to achieve control. The relation can suggest a failure of the earlier practical confidence to contain moral or mental consequences. Explain the connection rather than announcing that a character changes and moving straight to plot summary.'],['Qualify the conclusion','The later scene can unsettle the earlier assurance without proving that a physical bloodstain remains visible or providing a modern clinical diagnosis. A comparative paragraph can argue for a shift in control while preserving the limits of what witnesses and audience can actually know. Choose a connective that expresses the relation accurately.']],details:[['a little water','The earlier remedy is presented as small and sufficient.'],['out … out','Repetition turns removal into an urgent demand.'],['I say','An insistence on command can expose its failure to secure control.']],people:[['Earlier Lady Macbeth','Presents a practical remedy with confidence.'],['Later Lady Macbeth','Performs repeated washing and speaks under observation.'],['Doctor and gentlewoman','Observe behaviour without possessing all its history.']],movement:[['Locate','Give both quotations their separate situations.'],['Analyse','Explain a precise word or pattern in each.'],['Connect','Show how the later scene tests the earlier assurance.'],['Qualify','Avoid literal or clinical claims beyond the evidence.']],challenge:['Which comparison goes beyond a change label?','The later repeated command unsettles the earlier claim that a small remedy is sufficient.','The two passages prove the hands have the same visible bloodstain for years.','Both speeches are identical in situation and effect.','The comparison explains a relation between two specific methods.','Connect little and repeated commands without inventing a physical fact.'],practice:[['What does little contribute?','It minimises the remedy apparently needed after the deed.','It reports the exact volume of water in a laboratory.','It proves the speaker feels nothing at any later point.','A small word can shape a claim of manageable consequences.','methods'],['Why analyse repetition in the later line?','An urgent command can expose difficulty in securing control.','Repetition always proves perfect calm.','It establishes a medical diagnosis by itself.','Connect the pattern to this scene without universal rules.','comparison'],['Which claim needs qualification?','The scene allows a reading of troubled control, not a clinical diagnosis.','The two passages occur at different points.','Lady Macbeth speaks in both passages.','Literary evidence can support an interpretation without proving a diagnosis.','limits']],check:[['What differs between the two moments?','An earlier assurance is tested by a later troubled performance.','Both are spoken to the same audience immediately before Duncan’s death.','The later speech is a public legal confession.','Situation determines how each utterance functions.','meaning'],['Which detail makes the relation specific?','Little suggests sufficiency while repeated out suggests an unachieved demand.','Both quotations contain letters.','Only the number of lines matters.','Compare methods that bear on the claim about control.','methods'],['What should not be asserted as a textual fact?','A visible physical bloodstain remains on her hands throughout the later scene.','Observers describe repeated hand-rubbing.','The later scene can recall the earlier washing claim.','Imagined stain and observable behaviour need to be kept distinct.','accuracy'],['What makes the paragraph analytical?','Explain how the second scene revises the significance of the first.','Retell both scenes without a connecting claim.','Insert a diagnostic label in place of analysis.','A comparison needs a reasoned relation and supporting methods.','argument']],writing:'Compare how Lady Macbeth’s relation to control is presented through washing in the two scenes. Analyse language from each and end with a qualified judgment about the earlier assurance.',rubric:['Preserve the separate dramatic situations of the two passages.','Explain a relation between precise methods rather than merely listing two examples.','Qualify what the scenes suggest without inventing literal stains or a clinical diagnosis.']}),
make({key:'workshop-14',title:'Timed whole-play argument assessment',scope:'Act 1 preparation · fresh Act 5 assessment',minutes:50,sources:[F('1/7'),F('5/3')],quote:'He’s here in double trust:',
cards:[['Prepare a line of reasoning, not a memorised essay','Macbeth’s recognition of double trust makes duties part of his own deliberation. Use it to practise a claim about the gap between acknowledged obligations and conduct. Preparation should build flexible reasoning: a later assessment asks about insecurity, so a prewritten paragraph on trust cannot simply be pasted in regardless of the task.'],['Balance close reading with a whole-play route','Start with what a supplied passage actually presents, analyse a precise method, and connect it to a relevant earlier or later moment. A connection must develop the argument rather than merely prove that you know another scene. Build a short route through ideas before drafting; chronological coverage alone is not a thesis.'],['Use time deliberately and preserve the first response','The independent workspace supplies a different Act 5 passage. Aim for about 45 minutes including planning and checking; this is advisory and no timer is enforced. Guidance stays hidden during the attempt. Your first submission is preserved separately from later revisions. This original practice is not an official exam paper and does not award an essay mark.']],details:[['double','The obligation has more than one basis.'],['trust','The language makes a relationship of duty explicit.'],['He’s here','The deliberation attends to the immediate situation of Duncan’s visit.']],people:[['Preparing writer','Practises connecting a detail with a wider argument.'],['Independent writer','Responds to the fresh passage and the actual question.'],['Later reviewer','Uses the preserved first response to identify a revision priority.']],movement:[['Plan','Choose a claim that addresses the actual task.'],['Read','Analyse the fresh passage before reaching for remembered material.'],['Connect','Use whole-play evidence to develop the line of reasoning.'],['Check','Review relevance, accuracy and sentence control before submitting.']],challenge:['Which preparation transfers best to a fresh assessment?','Practise adapting a claim to the supplied passage and the actual question.','Memorise one essay and use it regardless of the prompt.','Avoid reading the passage because another scene is familiar.','Flexible evidence selection serves the question being asked.','Check whether the chosen evidence answers this task, not merely a familiar theme.'],practice:[['How should whole-play evidence be used?','Develop the argument made from the supplied passage.','Replace all close reading with a plot synopsis.','List every act without explaining relevance.','A whole-play connection should change or strengthen the reasoning.','structure'],['What is the status of the suggested time?','An advisory budget, not an enforced timer or official paper.','An automatic exam grade after 45 minutes.','A guarantee that every pupil writes at the same rate.','The workspace saves writing without policing time or external resources.','conditions'],['What should checking prioritise?','Relevance to the question, evidence accuracy and clear sentences.','Adding quotations whose wording is invented.','Replacing an argument with a longer plot summary.','Editing should improve the response’s substance and control.','editing']],check:[['What makes a whole-play connection useful?','It develops the claim established through the passage.','It is unrelated but comes from another act.','It replaces the need to address the question.','Relevance matters more than coverage for its own sake.','meaning'],['What should a writer do with an unfamiliar passage?','Read its specific language and situation before applying remembered ideas.','Ignore it and paste a memorised essay.','Assume it means the same as the teaching extract.','A fresh task requires an evidence-led response.','transfer'],['What happens to the first independent submission?','It is preserved separately from later revisions.','It is automatically replaced whenever a draft changes.','It receives an official AQA mark from the knowledge checks.','The writing record supports later human review without a false mark.','assessment'],['Which final edit is worthwhile?','Correct a misattributed reference and clarify its link to the argument.','Add a historical fact unrelated to the claim.','Delete all qualification so every effect becomes certain.','Accuracy and a clear relation between evidence and claim improve reasoning.','editing']],writing:'Practise a short argument about trust from Act 1, then start the independent task and respond to its fresh passage about insecurity.',rubric:['Address the actual question with a sustained and relevant line of reasoning.','Analyse the supplied passage closely and connect it to precise whole-play evidence.','Use accurate references and controlled sentences; qualify claims beyond the text.'],extra:{independentWriting:true,independentTaskType:'extract-to-whole',independentTaskLabel:'Original extract-to-whole practice, not an official exam paper.',independentIntro:'Aim for about 45 minutes including planning and checking. Timing is advisory, not enforced. Read the supplied passage and develop your own argument; teaching guidance is hidden until you submit. Your first response is saved separately from revisions.',independentPrompt:'Starting with this passage, explore how Shakespeare presents Macbeth’s insecurity. Write about the language and situation in this passage and how insecurity develops elsewhere in the play.',independentExtractLabel:'Macbeth · Act 5, scene 3 · Macbeth speaking',independentExtract:'I have lived long enough. My way of life\nIs fall’n into the sere, the yellow leaf,\nAnd that which should accompany old age,\nAs honor, love, obedience, troops of friends,\nI must not look to have, but in their stead\nCurses, not loud but deep, mouth-honor, breath\nWhich the poor heart would fain deny and dare not.'}}),
make({key:'workshop-15',title:'Feedback-led redrafting and delayed recall',scope:'Whole-play response · diagnose, revise and return',sources:[F('1/7'),F('5/3')],quote:'False face must hide what the false heart doth know.',
cards:[['Choose a revision priority from actual writing','Bring your first assessment response into this workshop, or use a draft you already have. Compare it with the criteria and any feedback actually received from a teacher. The app does not invent a mark or pretend a teacher has commented. Choose one specific weakness: an unsupported claim, an inaccurate reference or a connection that does not answer the task.'],['Revise the reasoning, not just the surface','For example, a claim that Macbeth is always confidently in control struggles to explain the Act 5 recognition of lost friendship. Qualify the claim and explain the evidence that requires the change. The false face line can help test an argument about outward confidence and inward knowledge, but use it only if that relation serves your question.'],['Keep evidence of change and return later','Save a version after revising and explain to yourself what changed and why. Your original independent submission remains intact. Return later to retrieve a supporting reference without looking, then verify it. Review schedules missed knowledge concepts; finishing this workshop now does not itself prove long-term retention or essay mastery.']],details:[['False face','An outward presentation is separated from inward knowledge.'],['must hide','The need to conceal makes a useful test of a claim about confidence.'],['false heart','The inward position is not simply identical to the public appearance.']],people:[['Original writer','Has a preserved first assessment response.'],['Reviewer','Uses criteria and any real feedback to identify a specific priority.'],['Revising writer','Changes reasoning while keeping the earlier response readable.']],movement:[['Diagnose','Identify one actual weakness in the response.'],['Revise','Change a claim, evidence choice or explanation to address it.'],['Compare','Read the old and new versions and explain the difference.'],['Retrieve later','Return after an interval and check remembered evidence.']],challenge:['Which change is a substantive redraft?','Qualify an always-confident claim using the Act 5 evidence of insecurity.','Change the font while leaving the unsupported claim untouched.','Invent a teacher’s mark to make the response look complete.','Revision should address a demonstrated weakness in the reasoning.','Identify what the change improves in the argument.'],practice:[['Where should a revision priority come from?','The actual response, criteria and any real feedback received.','A fabricated teacher comment or automatic essay grade.','A random word chosen without reading the draft.','Diagnosis needs evidence from the writing being revised.','diagnosis'],['Why preserve the first response?','It lets the writer compare the reasoning before and after revision.','It guarantees the later version earns full marks.','It prevents all future editing.','A record of change supports reflection without promising attainment.','versions'],['What makes later recall useful?','Try to retrieve after an interval, then verify the evidence.','Reread immediately and declare permanent mastery.','Remember a quotation confidently without checking accuracy.','Delayed retrieval and source checking test different things from immediate familiarity.','recall']],check:[['Which revision addresses an evidence gap?','Add a relevant verified reference and explain how it supports the claim.','Append an unrelated fact solely to increase length.','Invent a quotation that agrees with the thesis.','A useful change improves the claim-evidence relation.','meaning'],['What does bringing in a response do?','Copies the saved first assessment text into an empty workshop draft.','Overwrites the original assessment submission.','Creates a teacher mark from knowledge-question scores.','The original and the revised workspace have separate purposes.','workflow'],['Which feedback claim is honest?','Use feedback actually received or review your own response against the criteria.','The app guarantees an unseen examiner has approved the essay.','Every saved draft has already been specialist marked.','Self-review and human feedback must not be confused with invented assessment.','review'],['What remains to be tested later?','Whether evidence can be recalled and used accurately after an interval.','Whether clicking Save proves permanent retention.','Whether every response is automatically a top-grade essay.','Immediate completion is not proof of durable knowledge or writing attainment.','retention']],writing:'Bring in your assessment response if available. Identify one weakness using the criteria or real feedback, revise the relevant passage, then save a version. Add a brief note explaining the substantive change.',rubric:['Identify a specific weakness using the actual writing and any real feedback.','Revise the relation between claim, verified evidence and explanation.','Compare versions honestly and plan later retrieval without claiming an automatic essay mark.'],extra:{revisionFrom:'lit.macbeth.workshop-14'}}),
make({topic:'carol',key:'workshop-01',title:'Stave 1 sustained reading and annotation',scope:'Stave 1 · narrative judgment and an image cluster',sources:[C],quote:'Oh! But he was a tight-fisted hand at the grindstone, Scrooge! a squeezing, wrenching, grasping, scraping, clutching, covetous, old sinner! Hard and sharp as flint, from which no steel had ever struck out generous fire; secret, and self-contained, and solitary as an oyster.',
cards:[['Read the voice as well as the description','Read the opening of Stave 1 in the complete linked text before isolating this paragraph. The narrator’s exclamation and accumulating judgments present Scrooge forcefully. These words are not Scrooge’s own self-description. Annotation should distinguish what is described from the attitude and method of the voice describing it.'],['Follow a cluster instead of collecting labels','The grasping actions, hard flint and closed oyster develop related ideas of withholding, hardness and separation. Choose a relation between details and explain it. Naming a list, simile and exclamation is only a start; analysis asks how their combination shapes this particular portrait rather than assuming every technique always has one effect.'],['Keep an inference open to later testing','The oyster image can suggest enclosure and separation. A reader may also consider a possibility of something valuable concealed within, but that is an inference to test against later change, not a guarantee contained literally in the sentence. Use the whole stave to check how hospitality, charity and Marley’s visit complicate the opening portrait.']],details:[['squeezing … clutching','An accumulation of actions gives withholding an active force.'],['flint','Hardness is linked to an absence of generous fire in the description.'],['oyster','A closed, solitary comparison supports a reading of enclosure.']],people:[['Narrator','Selects images and makes emphatic judgments.'],['Scrooge','Is described here rather than speaking these words.'],['Reader','Tests the opening portrait against the rest of the stave.']],movement:[['Read','Follow the opening within the complete stave.'],['Distinguish','Separate narrative judgment from character speech.'],['Connect','Explain a relation within the image cluster.'],['Test','Revisit the inference as the stave develops.']],challenge:['Which annotation develops a defensible argument?','The clustered grasping actions and closed oyster image build a portrait of withholding and separation.','The narrator is quoting Scrooge’s exact description of himself.','The oyster guarantees a particular ending without any further evidence.','Connected details support an interpretation more precisely than a label alone.','Identify who describes Scrooge and how the details work together.'],practice:[['Whose voice delivers the displayed description?','The narrator’s descriptive voice.','Scrooge directly introducing himself to Fred.','Marley confessing his own habits.','Narrative voice and character speech have different roles.','voice'],['What makes an annotation analytical?','Explain how a chosen detail shapes the portrait of withholding.','Write simile in the margin and stop.','Count punctuation without considering its function.','A method label needs an account of meaning in context.','methods'],['How should an oyster-based possibility of change be treated?','As an inference to test against later narrative evidence.','As a literal promise that determines every later event.','As proof that Scrooge lives under the sea.','Interpretive possibility differs from a guaranteed outcome.','inference']],check:[['Which distinction is necessary here?','The narrator describes Scrooge; Scrooge is not speaking the paragraph.','Every descriptive word is Scrooge’s spoken confession.','The paragraph has no narrative perspective.','Attribution matters to the presentation of judgment.','meaning'],['How do the accumulated actions contribute?','They make withholding feel forceful and repeated.','They prove an exact scientific measurement of greed.','They make the later story unnecessary.','Explain a pattern’s function without turning it into literal data.','methods'],['Which claim needs later evidence?','An enclosure image may leave room for concealed value or change.','The paragraph compares Scrooge with an oyster.','The narrator uses emphatic judgment.','A possible implication should be tested through the developing text.','interpretation'],['What should follow a close reading of this paragraph?','Read how the rest of Stave 1 tests and extends the portrait.','Assume one paragraph substitutes for the whole novella.','Invent a speech that confirms the desired ending.','Sustained reading checks an initial inference against development.','structure']],writing:'Annotate three connected details in the opening portrait, then write a paragraph explaining how the narrator constructs Scrooge’s withholding. Qualify one inference and test it against a later moment in Stave 1.',rubric:['Distinguish narrative judgment from the character’s own speech.','Connect precise details into a reasoned account of the portrait.','Test a qualified inference against the wider stave rather than treating a simile as a guarantee.']}),
make({topic:'carol',key:'workshop-02',title:'Stave 2 memory and narrative viewpoint workshop',scope:'Stave 2 · child, adult witness and narrator',sources:[C],quote:'“The school is not quite deserted,” said the Ghost. “A solitary child, neglected by his friends, is left there still.”\n\nScrooge said he knew it. And he sobbed.',
cards:[['Keep the layers of the scene distinct','The Ghost identifies a solitary child in a remembered school scene, while the adult Scrooge recognises the situation and sobs. The narrator reports these responses. Past child, present adult witness and narrative voice are related but not interchangeable. Trace who speaks, who experiences and who observes before making a claim about memory.'],['Explain how perspective changes sympathy','The adult’s emotion invites a reconsideration of the earlier portrait of coldness. It gives a reader access to vulnerability without requiring that every present action be excused. Compare this remembered loneliness with Scrooge’s later treatment of others: an explanation of conduct is not automatically a moral defence of it.'],['Read memory as narrative construction','The journey selects and orders episodes for Scrooge and the reader. The brief report of sobbing can interrupt a detached view of the child and make the adult’s response immediate. Explain the method without treating the supernatural visit as an independently verified biography or assuming every reader experiences exactly the same emotion.']],details:[['solitary child','The Ghost’s description makes childhood isolation explicit.'],['he knew it','Recognition connects the adult witness with the remembered scene.'],['And he sobbed','A brief reported response foregrounds present emotion.']],people:[['Child Scrooge','Appears within the remembered school scene.'],['Adult Scrooge','Witnesses, recognises and responds emotionally.'],['Narrator','Reports the encounter and shapes the reader’s access to it.']],movement:[['Encounter','Enter a selected remembered scene.'],['Recognise','Connect adult knowledge with the child’s situation.'],['Respond','Read the immediate emotional reaction.'],['Reconsider','Complicate the earlier portrait without erasing responsibility.']],challenge:['Which reading keeps sympathy and responsibility distinct?','The memory reveals vulnerability without automatically excusing later conduct.','A lonely childhood makes every later harmful choice morally right.','The adult and child are two unrelated characters.','Explanation can complicate judgment without removing it.','Ask what the memory helps explain and what it does not justify.'],practice:[['Who sobs in the displayed passage?','The adult Scrooge witnessing the remembered scene.','The narrator announcing personal memories.','Fred speaking at the final dinner.','The remembered child and present witness occupy different narrative positions.','viewpoint'],['How can the short final sentence work?','It foregrounds the adult’s immediate emotional response.','It proves that every reader must cry.','It makes the narrator identical to the Ghost.','Relate sentence form to the response presented, not a guaranteed audience emotion.','methods'],['Why call the memory sequence a narrative construction?','Episodes are selected and ordered to develop recognition and response.','It is a complete independent biography with no framing.','The events have no relationship to later change.','Selection and arrangement shape the journey’s significance.','structure']],check:[['Which account accurately separates the scene’s layers?','A remembered child is viewed by adult Scrooge and presented through a narrator.','The narrator is literally the lonely schoolchild.','The Ghost and adult Scrooge are the same speaker throughout.','Track who speaks, experiences and reports.','meaning'],['What does recognition connect?','The adult witness’s knowledge with the remembered school scene.','Fred’s dinner with the final Ghost’s grave.','The narrator’s childhood with Marley’s business accounts.','The words locate a personal relation to the remembered event.','methods'],['Which judgment is properly qualified?','The memory can encourage sympathy while leaving later responsibility open to judgment.','Past loneliness automatically justifies every later action.','No emotional response can affect a reader’s view.','A complex portrait can combine vulnerability and accountability.','interpretation'],['What develops a whole-novella argument?','Compare remembered isolation with Scrooge’s later treatment of other isolated people.','List the scene without explaining any later relation.','Assume the first memory provides a complete biography.','A connection should explain how perspective bears on conduct and change.','argument']],writing:'How does Dickens use the adult Scrooge’s response to the lonely schoolchild to complicate a reader’s judgment? Distinguish the layers of viewpoint and connect the memory with a later relationship.',rubric:['Distinguish remembered child, adult witness and narrative voice accurately.','Analyse a precise method that presents recognition or emotion.','Connect vulnerability with later conduct without treating explanation as automatic excuse.']})
];
